import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { callerHeader, renderCallerWorkflow } from "./render";

const template = readFileSync(join(import.meta.dir, "..", "..", "templates", "wachiman-review-caller.yml"), "utf8");
const header = callerHeader({ version: "1.9.0", now: "2026-11-09T12:00:00.000Z" });

describe("callerHeader", () => {
  test("names the version and the date, and says who pays for Actions and what local runs use", () => {
    expect(header).toBe(
      "# Generated by wachiman init 1.9.0 on 2026-11-09; Actions is billed through the ANTHROPIC_API_KEY secret; local runs use your signed-in claude.",
    );
  });
});

describe("renderCallerWorkflow on the real template", () => {
  test("replaces both anchors and changes nothing else: the diff is two lines plus the header", () => {
    const out = renderCallerWorkflow(template, { operator: "octocat", tag: "v2.0.1", header });
    const before = template.split("\n");
    const after = out.split("\n");
    expect(after[0]).toBe(header);
    const body = after.slice(1);
    expect(body.length).toBe(before.length);
    const changed = before.flatMap((line, i) => (line === body[i] ? [] : [{ before: line, after: body[i] }]));
    expect(changed).toHaveLength(2);
    expect(changed[0].before).toBe("    uses: niway-dev/wachiman/.github/workflows/review.yml@v1.5.0");
    expect(changed[0].after).toBe("    uses: niway-dev/wachiman/.github/workflows/review.yml@v2.0.1");
    expect(changed[1].before).toBe("      operator: EDIT-THIS-github-login");
    expect(changed[1].after).toBe("      operator: octocat");
  });

  test("without a header the output is the template with the two lines replaced", () => {
    const out = renderCallerWorkflow(template, { operator: "me", tag: "v1.5.0" });
    expect(out).toBe(template.replace("EDIT-THIS-github-login", "me"));
  });

  test("a commit SHA pins like a tag", () => {
    const sha = "0123456789abcdef0123456789abcdef01234567";
    expect(renderCallerWorkflow(template, { operator: "me", tag: sha })).toContain(`review.yml@${sha}\n`);
  });

  test("the maintained triggers, permissions and secret ship as written", () => {
    const out = renderCallerWorkflow(template, { operator: "me", tag: "v1.5.0" });
    for (const kept of [
      "pull_request: { types: [opened, ready_for_review, synchronize] }",
      "permissions: { contents: read, pull-requests: write, issues: read }",
      "ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}",
    ]) {
      expect(out).toContain(kept);
    }
  });

  test("characters that mean something to String.replace are written literally", () => {
    const out = renderCallerWorkflow(template, { operator: "a-$&-b", tag: "v1.5.0" });
    expect(out).toContain("operator: a-$&-b\n");
  });
});

describe("renderCallerWorkflow throws when a template lacks an anchor", () => {
  test("no operator placeholder", () => {
    const broken = template.replace("EDIT-THIS-github-login", "someone");
    expect(() => renderCallerWorkflow(broken, { operator: "me", tag: "v1.5.0" })).toThrow(/operator/);
  });

  test("no review.yml pin", () => {
    const broken = template.replace("review.yml@v1.5.0", "review.yml");
    expect(() => renderCallerWorkflow(broken, { operator: "me", tag: "v1.5.0" })).toThrow(/review\.yml@/);
  });

  test("an anchor found twice is as wrong as one not found", () => {
    expect(() => renderCallerWorkflow(`${template}\n# operator: EDIT-THIS-github-login\n`, { operator: "me", tag: "v1.5.0" })).toThrow(/operator/);
  });
});
